// ============================================================
// MTNC TABLET OS v3.0.2 — MAIN RUNTIME (100% NON-BLOCKING MODALS)
// ============================================================
const DK_POLITI_WALLPAPER = "data:image/png;base64,";
const DK_REGIONH_WALLPAPER = "data:image/png;base64,";

const NationalEmblems = {
  da_police: `<svg viewBox="0 0 400 400" fill="none" xmlns="http://www.w3.org/2000/svg"><circle cx="200" cy="200" r="180" stroke="#3b82f6" stroke-width="6" fill="none"/><text x="200" y="225" font-family="'Inter', sans-serif" font-weight="900" font-size="34" fill="#ffffff" text-anchor="middle" letter-spacing="4">POLITI</text></svg>`,
  en_police: `<svg viewBox="0 0 400 400" fill="none" xmlns="http://www.w3.org/2000/svg"><circle cx="200" cy="200" r="180" stroke="#3b82f6" stroke-width="6" fill="none"/><text x="200" y="200" font-family="'Inter', sans-serif" font-weight="900" font-size="28" fill="#ffffff" text-anchor="middle" letter-spacing="2">POLICE 911</text></svg>`,
  en_ambulance: `<svg viewBox="0 0 400 400" fill="none" xmlns="http://www.w3.org/2000/svg"><circle cx="200" cy="200" r="180" stroke="#06b6d4" stroke-width="6" fill="none"/><text x="200" y="200" font-family="'Inter', sans-serif" font-weight="900" font-size="28" fill="#ffffff" text-anchor="middle" letter-spacing="3">EMS 911</text></svg>`,
  de_police: `<svg viewBox="0 0 400 400" fill="none" xmlns="http://www.w3.org/2000/svg"><circle cx="200" cy="200" r="180" stroke="#3b82f6" stroke-width="6" fill="none"/><text x="200" y="200" font-family="'Inter', sans-serif" font-weight="900" font-size="32" fill="#ffffff" text-anchor="middle" letter-spacing="4">POLIZEI</text></svg>`,
  de_ambulance: `<svg viewBox="0 0 400 400" fill="none" xmlns="http://www.w3.org/2000/svg"><circle cx="200" cy="200" r="180" stroke="#06b6d4" stroke-width="6" fill="none"/><text x="200" y="200" font-family="'Inter', sans-serif" font-weight="900" font-size="24" fill="#ffffff" text-anchor="middle" letter-spacing="2">NOTARZT 112</text></svg>`,
  sv_police: `<svg viewBox="0 0 400 400" fill="none" xmlns="http://www.w3.org/2000/svg"><circle cx="200" cy="200" r="180" stroke="#3b82f6" stroke-width="6" fill="none"/><text x="200" y="225" font-family="'Inter', sans-serif" font-weight="900" font-size="34" fill="#ffffff" text-anchor="middle" letter-spacing="4">POLIS</text></svg>`,
  sv_ambulance: `<svg viewBox="0 0 400 400" fill="none" xmlns="http://www.w3.org/2000/svg"><circle cx="200" cy="200" r="180" stroke="#06b6d4" stroke-width="6" fill="none"/><text x="200" y="200" font-family="'Inter', sans-serif" font-weight="900" font-size="24" fill="#ffffff" text-anchor="middle" letter-spacing="2">AMBULANS</text></svg>`,
  no_police: `<svg viewBox="0 0 400 400" fill="none" xmlns="http://www.w3.org/2000/svg"><circle cx="200" cy="200" r="180" stroke="#3b82f6" stroke-width="6" fill="none"/><text x="200" y="225" font-family="'Inter', sans-serif" font-weight="900" font-size="34" fill="#ffffff" text-anchor="middle" letter-spacing="4">POLITI</text></svg>`,
  no_ambulance: `<svg viewBox="0 0 400 400" fill="none" xmlns="http://www.w3.org/2000/svg"><circle cx="200" cy="200" r="180" stroke="#06b6d4" stroke-width="6" fill="none"/><text x="200" y="200" font-family="'Inter', sans-serif" font-weight="900" font-size="24" fill="#ffffff" text-anchor="middle" letter-spacing="2">AMBULANSE 113</text></svg>`
};

const App = {
  state: {
    isOpen: false,
    currentApp: 'home',
    theme: 'modern',
    session: { isStaff: false },
    profile: {},
    jobsData: null,
    vehicles: [],
    houses: [],
    reports: [],
    adminPlayers: [],
    adminStaff: [],
    adminAuditLogs: [],
    adminVehMatches: [],
    bossData: null
  },

  init() {
    this.startClock();
    this.setupEventListeners();
    let savedTheme = 'modern';
    try { if (typeof window !== 'undefined' && window.localStorage) savedTheme = window.localStorage.getItem('mtnc_tablet_theme') || 'modern'; } catch(e) {}
    this.state.theme = savedTheme;
    this.applyTheme(savedTheme);
    this.renderAppGrid();
    this.updateStaticLabels();
  },

  startClock() {
    const updateTime = () => {
      const now = new Date();
      const hours = String(now.getHours()).padStart(2, '0');
      const mins = String(now.getMinutes()).padStart(2, '0');
      const timeStr = `${hours}:${mins}`;
      const clockEl = document.getElementById('os-clock');
      const homeClockEl = document.getElementById('home-time');
      if (clockEl) clockEl.textContent = timeStr;
      if (homeClockEl) homeClockEl.textContent = timeStr;
    };
    updateTime();
    setInterval(updateTime, 1000);
  },

  setTheme(themeName) {
    this.state.theme = themeName;
    try {
      if (typeof window !== 'undefined' && window.localStorage) {
        window.localStorage.setItem('mtnc_tablet_theme', themeName);
      }
    } catch(e) {}
    this.applyTheme(themeName);
    this.renderCurrentView();
    this.showToast('🎨 Tema skiftet til ' + themeName.toUpperCase() + '!', 'success');
  },

  applyTheme(themeName) {
    const container = document.getElementById('tablet-container');
    if (!container) return;
    const isHidden = container.classList.contains('hidden');
    container.className = 'tablet-container theme-' + (themeName || 'modern') + (isHidden ? ' hidden' : '');

    let curLang = 'da';
    try { if (typeof window !== 'undefined' && window.localStorage) curLang = window.localStorage.getItem('mtnc_tablet_lang') || 'da'; } catch(e) {}

    const badgeChip = document.querySelector('.status-badge-chip');
    if (badgeChip) {
      if (themeName === 'police') {
        badgeChip.textContent = t('service_police_badge') || 'POLICE';
      } else if (themeName === 'ambulance') {
        badgeChip.textContent = t('service_ems_badge') || 'EMS';
      } else {
        badgeChip.textContent = 'MTNC 5G';
      }
    }

    // 1. Full-Bleed Wallpaper Layer
    const wallpaperImg = document.getElementById('os-wallpaper');
    if (wallpaperImg) {
      if (themeName === 'police' && curLang === 'da') {
        wallpaperImg.src = DK_POLITI_WALLPAPER;
        wallpaperImg.classList.add('active');
      } else if (themeName === 'ambulance' && curLang === 'da') {
        wallpaperImg.src = DK_REGIONH_WALLPAPER;
        wallpaperImg.classList.add('active');
      } else {
        wallpaperImg.src = '';
        wallpaperImg.classList.remove('active');
      }
    }

    // 2. International Dynamic SVG Watermarks (Non-Danish)
    const watermarkEl = document.getElementById('theme-watermark');
    if (watermarkEl) {
      if (themeName === 'police' && curLang !== 'da') {
        const emblemKey = `${curLang}_police`;
        watermarkEl.innerHTML = NationalEmblems[emblemKey] || NationalEmblems.en_police;
        watermarkEl.classList.add('visible');
      } else if (themeName === 'ambulance' && curLang !== 'da') {
        const emblemKey = `${curLang}_ambulance`;
        watermarkEl.innerHTML = NationalEmblems[emblemKey] || NationalEmblems.en_ambulance;
        watermarkEl.classList.add('visible');
      } else {
        watermarkEl.innerHTML = '';
        watermarkEl.classList.remove('visible');
      }
    }
  },

  setLanguage(langCode) {
    if (!Locales[langCode]) return;
    try {
      if (typeof window !== 'undefined' && window.localStorage) {
        window.localStorage.setItem('mtnc_tablet_lang', langCode);
      }
    } catch(e) {}
    this.applyTheme(this.state.theme || 'modern');
    this.renderAppGrid();
    this.renderCurrentView();
    this.updateStaticLabels();
    this.showToast(`🌐 Sprog skiftet til ${Locales[langCode].name}!`, 'success');
  },

  updateStaticLabels() {
    const elSystem = document.getElementById('lbl-system-status');
    const elGateway = document.getElementById('lbl-gateway-status');
    const elChar = document.getElementById('lbl-char');
    const elActiveJob = document.getElementById('lbl-active-job');
    const elDutyStatus = document.getElementById('lbl-duty-status');
    const elHomeIndicator = document.getElementById('home-indicator');

    if (elSystem) elSystem.textContent = t('systemStatus') || 'System Status';
    if (elGateway) elGateway.textContent = t('connected') || '🟢 Forbundet';
    if (elChar) elChar.textContent = t('character') || 'Karakter';
    if (elActiveJob) elActiveJob.textContent = t('activeJob') || 'Aktivt Job';
    if (elDutyStatus) elDutyStatus.textContent = t('dutyStatus') || 'Vagtstatus';
    if (elHomeIndicator) elHomeIndicator.title = t('closeTablet') || 'Luk Tablet';
  },

  setupEventListeners() {
    window.addEventListener('message', (event) => {
      const { action, data, open, msg, toastType } = event.data;
      if (action === 'toggleTablet') {
        this.toggle(open);
      } else if (action === 'initTablet') {
        this.state.session = data.session || {};
        this.state.profile = data.profile || {};
        
        const charNameEl = document.getElementById('widget-char-name');
        const charJobEl = document.getElementById('widget-char-job');
        const dutyEl = document.getElementById('widget-duty-status');
        if (charNameEl) charNameEl.textContent = this.state.profile.name || 'Thomas';
        if (charJobEl && this.state.profile.primaryJob) {
          charJobEl.textContent = `${this.state.profile.primaryJob.label} · ${this.state.profile.primaryJob.gradeLabel}`;
        }
        if (dutyEl && this.state.profile.primaryJob) {
          dutyEl.textContent = this.state.profile.primaryJob.duty ? (t('onDutyShort') || '🟢 På vagt') : (t('offDutyShort') || '⚪ Fri');
        }

        this.applyTheme(this.state.theme || 'modern');
        this.renderAppGrid();
        this.renderCurrentView();
      } else if (action === 'setVehicles') {
        this.state.vehicles = data || [];
        if (this.state.currentApp === 'vehicles') this.renderCurrentView();
      } else if (action === 'setJobs') {
        this.state.jobsData = data;
        if (this.state.currentApp === 'jobs') this.renderCurrentView();
      } else if (action === 'setReports') {
        this.state.reports = data || [];
        if (this.state.currentApp === 'reports' || this.state.currentApp === 'admin') this.renderCurrentView();
      } else if (action === 'setAdminAuditLogs') {
        this.state.adminAuditLogs = data || [];
        if (this.state.currentApp === 'admin') this.renderCurrentView();
      } else if (action === 'setAdminStaffList') {
        this.state.adminStaff = data || [];
        if (this.state.currentApp === 'admin') this.renderCurrentView();
      } else if (action === 'setBossData') {
        this.state.bossData = data || {};
        if (this.state.currentApp === 'boss') this.renderCurrentView();
      } else if (action === 'setAdminPlayers') {
        this.state.adminPlayers = data || [];
        if (this.state.currentApp === 'admin') this.renderCurrentView();
      } else if (action === 'setAdminVehicleSearch') {
        this.state.adminVehMatches = data || [];
        if (this.state.currentApp === 'admin') this.renderCurrentView();
      } else if (action === 'showAnnouncementBanner') {
        const banner = document.getElementById('server-announcement-banner');
        const textEl = document.getElementById('announcement-text');
        const authorEl = document.getElementById('announcement-author');
        if (banner && textEl) {
          textEl.textContent = data.message || '';
          if (authorEl) authorEl.textContent = '📢 SERVER ANNOUNCEMENT (' + (data.author || 'ADMINISTRATION') + ')';
          banner.classList.remove('hidden');
          if (App.announcementTimer) clearTimeout(App.announcementTimer);
          App.announcementTimer = setTimeout(() => {
            banner.classList.add('hidden');
          }, 9500);
        }
      } else if (action === 'notify') {
        this.showToast(msg, toastType || 'info');
      }
    });

    document.getElementById('home-indicator')?.addEventListener('click', () => this.close());
    document.querySelectorAll('.dock-app-icon').forEach(btn => {
      btn.addEventListener('click', () => this.openApp(btn.dataset.open));
    });

    window.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        const modal = document.getElementById('os-modal-backdrop');
        if (modal && !modal.classList.contains('hidden')) {
          this.closeModal();
        } else {
          this.close();
        }
      }
    });
  },

  toggle(state) {
    this.state.isOpen = state !== undefined ? state : !this.state.isOpen;
    const container = document.getElementById('tablet-container');
    if (container) {
      if (this.state.isOpen) {
        container.classList.remove('hidden');
        this.openApp('home');
      } else {
        container.classList.add('hidden');
        this.closeModal();
      }
    }
  },

  close() {
    this.toggle(false);
    API.post('closeTablet');
  },

  openApp(appId) {
    this.state.currentApp = appId;
    document.querySelectorAll('.os-view').forEach(view => {
      view.classList.remove('active');
      view.classList.add('hidden');
    });
    const target = document.getElementById(`view-${appId}`);
    if (target) {
      target.classList.remove('hidden');
      target.classList.add('active');
      this.renderCurrentView();
    }
    if (appId === 'jobs') API.post('getJobs');
    if (appId === 'vehicles') API.post('getVehicles');
    if (appId === 'boss') API.post('getBossData');
    if (appId === 'reports') API.post('getReports');
    if (appId === 'admin') {
      API.post('getReports');
      API.post('adminGetPlayers');
      API.post('adminGetStaffList');
      API.post('adminGetAuditLogs');
    }
  },

  renderAppGrid() {
    const grid = document.getElementById('desktop-app-grid');
    if (!grid) return;

    const isStaff = this.state.session?.isStaff || false;
    const isBoss = this.state.profile?.isBoss || this.state.profile?.primaryJob?.isBoss || false;

    const appsToShow = getAppsList().filter(a => {
      if (a.isStaffOnly && !isStaff) return false;
      if (a.isBossOnly && !isBoss) return false;
      return true;
    });

    grid.innerHTML = appsToShow.map(a => `
      <div class="app-icon" onclick="App.openApp('${a.id}')">
        <div class="icon-squircle" style="background: ${a.bg || 'linear-gradient(135deg, #2563eb, #1d4ed8)'};">${a.icon}</div>
        <span class="icon-title">${a.name}</span>
      </div>
    `).join('');
  },

  renderCurrentView() {
    const appId = this.state.currentApp;
    if (appId === 'home') return;
    const renderer = Renderers[appId];
    const target = document.getElementById(`view-${appId}`);
    if (target && typeof renderer === 'function') {
      target.innerHTML = renderer(this.state);
    }
  },

  setAdminTab(tabName) {
    this.state.adminTab = tabName;
    if (tabName === 'players') API.post('adminGetPlayers');
    if (tabName === 'staff') API.post('adminGetStaffList');
    if (tabName === 'audit') API.post('adminGetAuditLogs');
    this.renderCurrentView();
  },

  refreshAdminData() {
    API.post('adminGetPlayers');
    API.post('getReports');
    API.post('adminGetStaffList');
    API.post('adminGetAuditLogs');
    this.showToast('Opdaterer admin data...', 'info');
  },

  // ============================================================
  // 💬 CUSTOM IN-GAME MODAL SYSTEM (CEF FREEZE PROOF)
  // ============================================================
  showModal(options) {
    const backdrop = document.getElementById('os-modal-backdrop');
    const titleEl = document.getElementById('modal-title');
    const bodyEl = document.getElementById('modal-body');
    const confirmBtn = document.getElementById('modal-confirm-btn');
    const cancelBtn = document.getElementById('modal-cancel-btn');
    if (!backdrop || !bodyEl || !confirmBtn) return;

    titleEl.textContent = options.title || 'Handling';
    confirmBtn.textContent = options.confirmText || 'Bekræft';
    if (cancelBtn) cancelBtn.textContent = options.cancelText || 'Annuller';

    let bodyHtml = '';
    if (options.message) {
      bodyHtml += `<p style="margin-bottom:8px;">${options.message}</p>`;
    }

    if (options.fields && Array.isArray(options.fields)) {
      bodyHtml += options.fields.map(f => {
        if (f.type === 'textarea') {
          return `
            <div class="modal-field-group">
              <label class="modal-label">${f.label}</label>
              <textarea id="${f.id}" class="sys-textarea" rows="3" placeholder="${f.placeholder || ''}">${f.value || ''}</textarea>
            </div>
          `;
        } else if (f.type === 'select') {
          return `
            <div class="modal-field-group">
              <label class="modal-label">${f.label}</label>
              <select id="${f.id}" class="sys-select">
                ${(f.options || []).map(opt => `<option value="${opt.value || opt}">${opt.label || opt}</option>`).join('')}
              </select>
            </div>
          `;
        } else {
          return `
            <div class="modal-field-group">
              <label class="modal-label">${f.label}</label>
              <input type="${f.type || 'text'}" id="${f.id}" class="sys-input" placeholder="${f.placeholder || ''}" value="${f.value || ''}">
            </div>
          `;
        }
      }).join('');
    }

    bodyEl.innerHTML = bodyHtml;
    backdrop.classList.remove('hidden');

    setTimeout(() => {
      const firstInput = bodyEl.querySelector('input, textarea, select');
      if (firstInput) firstInput.focus();
    }, 50);

    confirmBtn.onclick = () => {
      const results = {};
      if (options.fields) {
        for (const f of options.fields) {
          const el = document.getElementById(f.id);
          results[f.id] = el ? el.value : '';
        }
      }
      this.closeModal();
      if (typeof options.onConfirm === 'function') {
        options.onConfirm(results);
      }
    };
  },

  closeModal() {
    const backdrop = document.getElementById('os-modal-backdrop');
    if (backdrop) backdrop.classList.add('hidden');
  },

  // 1. Staff Management Modals
  promptAddStaff() {
    this.showModal({
      title: '🛡️ Opret Nyt Staff Medlem',
      fields: [
        { id: 'ident', label: 'Spiller Identifier (Discord / License / FiveM)', placeholder: 'F.eks. discord:737367235315630132 eller license:...' },
        { id: 'name', label: 'Staff Navn', placeholder: 'F.eks. Thomas' },
        { id: 'rank', label: 'Staff Rang', type: 'select', options: [
          { value: 'moderator', label: 'Moderator' },
          { value: 'admin', label: 'Administrator' },
          { value: 'superadmin', label: 'Superadmin' }
        ]}
      ],
      confirmText: 'Opret Medlem',
      onConfirm: (data) => {
        if (!data.ident || !data.ident.trim()) return this.showToast('Identifier kan ikke være tom!', 'warning');
        API.post('adminAddStaff', { identifier: data.ident.trim(), name: (data.name || 'Staff').trim(), rank: data.rank });
      }
    });
  },

  promptChangeStaffRank(id, name) {
    this.showModal({
      title: '👔 Skift Rang for ' + name,
      fields: [
        { id: 'rank', label: 'Vælg Ny Rang', type: 'select', options: [
          { value: 'moderator', label: 'Moderator' },
          { value: 'admin', label: 'Administrator' },
          { value: 'superadmin', label: 'Superadmin' }
        ]}
      ],
      confirmText: 'Gem Rang',
      onConfirm: (data) => {
        API.post('adminUpdateStaffRank', { id: id, rank: data.rank });
      }
    });
  },

  confirmRemoveStaff(id, name) {
    this.showModal({
      title: '🗑️ Bekræft Fjernelse',
      message: 'Er du sikker på, at du vil fratage ' + name + ' staff-rettigheder?',
      confirmText: 'Ja, Fjern Staff',
      onConfirm: () => {
        API.post('adminRemoveStaff', { id: id });
      }
    });
  },

  confirmClearAuditLogs() {
    this.showModal({
      title: '🧹 Ryd Hele Revisionsloggen',
      message: 'Er du sikker på, at du vil rydde alle audit logs permanent fra databasen?',
      confirmText: 'Ja, Ryd Logbog',
      onConfirm: () => {
        API.post('adminClearAuditLogs');
      }
    });
  },

  // 2. Server Announcement Modal
  promptAnnounce() {
    this.showModal({
      title: '📢 Udsend Server Announcement',
      fields: [
        { id: 'msg', label: 'Meddelelse til alle online spillere', type: 'textarea', placeholder: 'Skriv serverbesked her...' }
      ],
      confirmText: 'Udsend Besked',
      onConfirm: (data) => {
        if (data.msg && data.msg.trim()) {
          API.post('adminServerAction', { action: 'announce', val1: data.msg.trim() });
          this.showToast('📢 Udsendte serverbesked!', 'success');
        }
      }
    });
  },

  // 3. Player Actions Modals
  promptGiveMoney(targetId, name) {
    this.showModal({
      title: '💰 Giv Penge til ' + name,
      fields: [
        { id: 'amount', label: 'Beløb (DKK)', type: 'number', placeholder: 'F.eks. 50000' },
        { id: 'type', label: 'Kontotype', type: 'select', options: [
          { value: 'cash', label: 'Kontanter (Cash)' },
          { value: 'bank', label: 'Bankkonto (Bank)' }
        ]}
      ],
      confirmText: 'Overfør Penge',
      onConfirm: (data) => {
        const amt = parseInt(data.amount);
        if (amt > 0) {
          API.post('adminPlayerAction', { targetSrc: targetId, action: 'giveMoney', val1: data.type, val2: amt });
          this.showToast(`💰 Overførte ${amt.toLocaleString()} DKK til ${name}`, 'success');
        }
      }
    });
  },

  promptSetJob(targetId, name) {
    this.showModal({
      title: '👔 Sæt Job for ' + name,
      fields: [
        { id: 'job', label: 'Job Navn (ID)', placeholder: 'F.eks. police, ambulance, mechanic' },
        { id: 'grade', label: 'Job Grad / Rang (Tal)', type: 'number', placeholder: '0 for elev, 1, 2 osv.', value: '0' }
      ],
      confirmText: 'Tildel Job',
      onConfirm: (data) => {
        if (data.job && data.job.trim()) {
          const grade = parseInt(data.grade) || 0;
          API.post('adminPlayerAction', { targetSrc: targetId, action: 'setJob', val1: data.job.trim().toLowerCase(), val2: grade });
          this.showToast(`👔 Satte job for ${name} til ${data.job}`, 'success');
        }
      }
    });
  },

      promptChangeVehColor() {
    this.openModal({
      title: '🎨 Vælg Køretøjsfarve Preset',
      fields: [
        { id: 'colorName', label: 'Vælg Farve (black, white, red, blue, gold, purple, green)', placeholder: 'f.eks. black eller red' }
      ],
      confirmText: '🎨 Skift Farve',
      onConfirm: (vals) => {
        const color = (vals.colorName || 'black').trim().toLowerCase();
        API.post('adminVehExtra', { action: 'color', color: color });
        this.showToast('Skiftede bilens farve til ' + color, 'success');
      }
    });
  },

    promptGiveWeapon(targetSrc = 0, charName = 'Dig Selv', defaultWeapon = 'weapon_combatpistol') {
    this.openModal({
      title: '🔫 Giv Våben & Vælg Skudantal (' + charName + ')',
      fields: [
        { id: 'weaponModel', label: 'Våben Model / Kode', placeholder: 'f.eks. weapon_combatpistol, weapon_carbinerifle...', defaultValue: defaultWeapon },
        { id: 'ammoCount', label: 'Antal Skud / Ammunition', placeholder: 'f.eks. 50, 100, 250, 500...', type: 'number', defaultValue: '250' }
      ],
      confirmText: '🔫 Giv Våben',
      onConfirm: (vals) => {
        const weapon = (vals.weaponModel || defaultWeapon).trim().toLowerCase();
        const ammo = parseInt(vals.ammoCount) || 250;
        if (!weapon) return this.showToast('Indtast venligst et våbennavn', 'warning');
        API.post('adminPlayerAction', { targetSrc: targetSrc, action: 'giveWeapon', val1: weapon, val2: ammo });
        this.showToast('Giver ' + weapon.toUpperCase() + ' (' + ammo + ' skud)...', 'info');
      }
    });
  },

  promptGiveItem(targetSrc, charName) {
    this.openModal({
      title: '🎁 Giv Item til Spiller',
      fields: [
        { id: 'itemName', label: 'Item Navn / Spawn Kode', placeholder: 'f.eks. phone, weapon_pistol, water_bottle...' },
        { id: 'itemAmount', label: 'Antal', placeholder: 'f.eks. 1 eller 5', type: 'number' }
      ],
      confirmText: '🎁 Giv Item',
      onConfirm: (vals) => {
        const item = (vals.itemName || '').trim();
        const amount = parseInt(vals.itemAmount) || 1;
        if (!item) return this.showToast('Angiv venligst et gyldigt item navn', 'warning');
        API.post('adminPlayerAction', { targetSrc: targetSrc, action: 'giveItem', val1: item, val2: amount });
        this.showToast('Giver ' + amount + 'x ' + item + '...', 'info');
      }
    });
  },

  promptSetGang(targetSrc, charName) {
    this.openModal({
      title: '🔫 Sæt Spiller Bande',
      fields: [
        { id: 'gangName', label: 'Bande Navn (f.eks. ballas, families, lostmc...)', placeholder: 'Indtast bande...' },
        { id: 'gangGrade', label: 'Rang / Grad (0, 1, 2, 3...)', placeholder: 'f.eks. 0 eller 1', type: 'number' }
      ],
      confirmText: '🔫 Sæt Bande',
      onConfirm: (vals) => {
        const gang = (vals.gangName || '').trim();
        const grade = parseInt(vals.gangGrade) || 0;
        if (!gang) return this.showToast('Indtast venligst et bande navn', 'warning');
        API.post('adminPlayerAction', { targetSrc: targetSrc, action: 'setGang', val1: gang, val2: grade });
        this.showToast('Sætter bande for ' + charName + '...', 'info');
      }
    });
  },

  promptWarnPlayer(targetId, name) {
    this.showModal({
      title: '⚠️ Advar Spiller: ' + name,
      fields: [
        { id: 'reason', label: 'Advarselsårsag', type: 'textarea', placeholder: 'Beskriv årsagen til advarslen...' }
      ],
      confirmText: 'Send Advarsel',
      onConfirm: (data) => {
        if (data.reason && data.reason.trim()) {
          API.post('adminPlayerAction', { targetSrc: targetId, action: 'warn', val1: data.reason.trim() });
          this.showToast('⚠️ Advarede ' + name, 'info');
        }
      }
    });
  },

  promptKickPlayer(targetId, name) {
    this.showModal({
      title: '👢 Kick Spiller: ' + name,
      fields: [
        { id: 'reason', label: 'Årsag til Kick', type: 'textarea', placeholder: 'Indtast årsag...' }
      ],
      confirmText: 'Kick Spiller',
      onConfirm: (data) => {
        if (data.reason && data.reason.trim()) {
          API.post('adminPlayerAction', { targetSrc: targetId, action: 'kick', val1: data.reason.trim() });
          this.showToast('👢 Kicket ' + name, 'info');
        }
      }
    });
  },

  promptBanPlayer(targetId, name) {
    this.showModal({
      title: '🔨 Permanent Ban: ' + name,
      fields: [
        { id: 'reason', label: 'Ban Årsag', type: 'textarea', placeholder: 'Indtast grundig begrundelse for udelukkelsen...' }
      ],
      confirmText: '🔨 Udfør Permanent Ban',
      onConfirm: (data) => {
        if (data.reason && data.reason.trim()) {
          API.post('adminPlayerAction', { targetSrc: targetId, action: 'ban', val1: data.reason.trim() });
          this.showToast('🔨 Bannede ' + name, 'error');
        }
      }
    });
  },

  promptSetBucket(targetId, name) {
    this.showModal({
      title: '🌐 Virtuel Dimension (Routing Bucket)',
      message: 'Sæt hvilken virtuel dimension ' + name + ' skal placeres i (0 = standard verden):',
      fields: [
        { id: 'bucket', label: 'Dimension ID (Tal)', type: 'number', value: '0' }
      ],
      confirmText: 'Skift Dimension',
      onConfirm: (data) => {
        const bucket = parseInt(data.bucket) || 0;
        API.post('adminPlayerAction', { targetSrc: targetId, action: 'setBucket', val1: bucket });
        this.showToast(`🌐 Satte dimension for ${name} til ${bucket}`, 'info');
      }
    });
  },

  promptChangePlate() {
    this.showModal({
      title: '🏷️ Skift Nummerplade',
      fields: [
        { id: 'plate', label: 'Ny Nummerplade (Maks 8 tegn)', placeholder: 'F.eks. ADMIN', value: 'ADMIN' }
      ],
      confirmText: 'Gem Nummerplade',
      onConfirm: (data) => {
        if (data.plate && data.plate.trim()) {
          API.post('adminVehExtra', { action: 'plate', plate: data.plate.trim().toUpperCase() });
        }
      }
    });
  },

  adminSpawnVehicle() {
    const input = document.getElementById('adminVehModel');
    const model = input && input.value ? input.value.trim() : 'adder';
    API.post('adminVehicleAction', { action: 'spawn', model: model });
    if (input) input.value = '';
  },

  adminSearchPlate() {
    const input = document.getElementById('adminPlateSearch');
    const plate = input && input.value ? input.value.trim() : '';
    if (plate) {
      API.post('adminSearchPlate', { plate: plate });
      this.showToast('Søger efter nummerplade: ' + plate, 'info');
    }
  },

  // 4. Boss App Modals
  promptBossDeposit() {
    this.showModal({
      title: '💵 Indsæt Penge på Firmakonto',
      fields: [
        { id: 'amount', label: 'Beløb (DKK)', type: 'number', placeholder: 'F.eks. 10000' }
      ],
      confirmText: 'Indsæt Penge',
      onConfirm: (data) => {
        const amt = parseInt(data.amount);
        if (amt > 0) API.post('bossDeposit', { amount: amt });
      }
    });
  },

  promptBossWithdraw() {
    this.showModal({
      title: '💳 Hæv Penge fra Firmakonto',
      fields: [
        { id: 'amount', label: 'Beløb (DKK)', type: 'number', placeholder: 'F.eks. 5000' }
      ],
      confirmText: 'Hæv Penge',
      onConfirm: (data) => {
        const amt = parseInt(data.amount);
        if (amt > 0) API.post('bossWithdraw', { amount: amt });
      }
    });
  },

  promptBossHire() {
    this.showModal({
      title: '➕ Ansæt Medarbejder i Firma',
      fields: [
        { id: 'targetId', label: 'Spiller Server ID (Online)', type: 'number', placeholder: 'F.eks. 1' },
        { id: 'grade', label: 'Start Rang / Grad (Tal)', type: 'number', placeholder: '0 for elev', value: '0' }
      ],
      confirmText: 'Ansæt Spiller',
      onConfirm: (data) => {
        const target = parseInt(data.targetId);
        if (target > 0) {
          API.post('bossHire', { targetId: target, grade: parseInt(data.grade) || 0 });
        }
      }
    });
  },

  promptBossSetGrade(citizenid, name) {
    this.showModal({
      title: '👔 Skift Stilling for ' + name,
      fields: [
        { id: 'grade', label: 'Ny Rang / Grad Nummer (0, 1, 2...)', type: 'number', value: '0' }
      ],
      confirmText: 'Opdater Stilling',
      onConfirm: (data) => {
        API.post('bossSetGrade', { citizenid: citizenid, grade: parseInt(data.grade) || 0 });
      }
    });
  },

  confirmBossFire(citizenid, name) {
    this.showModal({
      title: '🚪 Afskedig Medarbejder',
      message: 'Er du sikker på, at du vil afskedige ' + name + ' fra firmaet?',
      confirmText: 'Ja, Afskedig',
      onConfirm: () => {
        API.post('bossFire', { citizenid: citizenid });
      }
    });
  },

  submitReport(e) {
    e.preventDefault();
    const cat = document.getElementById('rep-category')?.value;
    const target = document.getElementById('rep-target')?.value;
    const reason = document.getElementById('rep-reason')?.value;
    API.post('createReport', { category: cat, targetId: target, reason: reason });
    this.openApp('home');
  },

  showToast(msg, type = 'info') {
    const deck = document.getElementById('toast-deck');
    if (!deck) return;
    const bubble = document.createElement('div');
    bubble.className = 'toast-bubble';
    bubble.textContent = msg;
    deck.appendChild(bubble);
    setTimeout(() => {
      bubble.remove();
    }, 4000);
  }
};

document.addEventListener('DOMContentLoaded', () => {
  App.init();
});
